// Some portions generated by Claude
// Some portions generated by Codex
// Inventory of the graph explorer's CSS: which class names the TSX uses, which the stylesheet defines, and which
// selectors are not scoped under .graph-explorer. Used by the unit test css-inventory.test.mjs and, with --print,
// for the STYLE-MAP review.
import { readdirSync, readFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const sourceDir = fileURLToPath(new URL("../src/main/frontend/graph-explorer/", import.meta.url));

function sourceFiles(directory) {
  return readdirSync(directory, { withFileTypes: true }).flatMap(entry => {
    const file = join(directory, entry.name);
    return entry.isDirectory() ? sourceFiles(file) : /\.tsx?$/.test(entry.name) ? [file] : [];
  });
}

/** CSS loaded by explorer modules, including component-local and lazily imported stylesheets. */
export function importedStylesheets(directory = sourceDir) {
  const files = new Set();
  for (const file of sourceFiles(directory)) {
    const source = readFileSync(file, "utf8");
    const imports = [
      /\bimport\s+(?!type\b)(?:["'](\.[^"']+\.css)["']|[^;"']*?\bfrom\s*["'](\.[^"']+\.css)["'])/g,
      /\bimport\s*\(\s*["'](\.[^"']+\.css)["']\s*\)/g,
    ];
    for (const pattern of imports) {
      for (const match of source.matchAll(pattern)) {
        files.add(resolve(dirname(file), match[1] ?? match[2]));
      }
    }
  }
  return [...files].sort();
}

/** Class names in className="..." attributes and in className={`...`} template literals (static parts only). */
export function usedClassNames(directory = sourceDir) {
  const names = new Map();
  for (const file of sourceFiles(directory).filter(file => file.endsWith(".tsx"))) {
    const source = readFileSync(file, "utf8");
    const record = (value) => value.split(/\s+/).filter((token) => /^[A-Za-z_][\w-]*$/.test(token))
      .forEach((token) => names.set(token, (names.get(token) ?? new Set()).add(relative(directory, file))));
    for (const match of source.matchAll(/className=(?:"([^"]*)"|\{`([^`]*)`\}|\{"([^"]*)"\})/g)) {
      const literal = match[1] ?? match[2] ?? match[3] ?? "";
      record(literal.replace(/\$\{[^}]*\}/g, " "));
    }
    // class names chosen inside expressions: "is-open", condition ? "a" : "b", `${base} ${suffix}`
    for (const match of source.matchAll(/className=\{([^}]*(?:\{[^}]*\}[^}]*)*)\}/g)) {
      for (const inner of match[1].matchAll(/["'`]([A-Za-z_][\w\s-]*)["'`]/g)) {
        record(inner[1].replace(/\$\{[^}]*\}/g, " "));
      }
    }
  }
  return names;
}

/** Splits a selector list on top-level commas only, so :is(a, b) and :not(a, b) stay whole. */
function splitSelectors(prelude) {
  const parts = [];
  let depth = 0;
  let current = "";
  for (const char of prelude) {
    if (char === "(") depth += 1;
    else if (char === ")") depth -= 1;
    if (char === "," && depth === 0) {
      parts.push(current);
      current = "";
    } else {
      current += char;
    }
  }
  parts.push(current);
  return parts.map((part) => part.trim()).filter(Boolean);
}

/** Class names mentioned by any selector of the stylesheet, and the selectors that are not scoped. */
export function stylesheetClassNames(cssPath = sourceDir + "graph-explorer.css") {
  const css = readFileSync(cssPath, "utf8").replace(/\/\*[\s\S]*?\*\//g, "");
  const defined = new Set();
  const unscoped = [];
  // Walk top-level and nested rule preludes (media/supports/keyframes blocks are entered, keyframe steps skipped).
  const preludes = [];
  let depth = 0;
  let buffer = "";
  const atStack = [];
  for (const char of css) {
    if (char === "{") {
      const prelude = buffer.trim();
      buffer = "";
      const isAt = prelude.startsWith("@");
      atStack.push(isAt ? prelude : null);
      if (!isAt && !atStack.some((at) => at && /^@keyframes|^@font-face|^@property/.test(at))) {
        preludes.push(prelude);
      }
      depth += 1;
    } else if (char === "}") {
      atStack.pop();
      depth -= 1;
      buffer = "";
    } else if (char === ";" && depth === 0) {
      buffer = "";
    } else {
      buffer += char;
    }
  }
  for (const prelude of preludes) {
    for (const selector of splitSelectors(prelude)) {
      for (const match of selector.matchAll(/\.(-?[_a-zA-Z]+[\w-]*)/g)) {
        defined.add(match[1]);
      }
      const scoped = /(^|[\s>+~])\.graph-explorer(\b|[\s>+~:.\[])/.test(selector)
        || /^html\[data-theme/.test(selector) || /^:root/.test(selector);
      if (!scoped) {
        unscoped.push(selector);
      }
    }
  }
  return { defined, unscoped };
}

export function inventory(directory = sourceDir) {
  const used = usedClassNames(directory);
  const defined = new Set();
  const unscoped = [];
  for (const file of importedStylesheets(directory)) {
    const stylesheet = stylesheetClassNames(file);
    for (const name of stylesheet.defined) defined.add(name);
    unscoped.push(...stylesheet.unscoped);
  }
  const missing = [...used.keys()].filter((name) => !defined.has(name)).sort();
  const unused = [...defined].filter((name) => !used.has(name)).sort();
  return { used, defined, unscoped, missing, unused };
}

if (process.argv.includes("--print")) {
  const result = inventory();
  console.log(`used: ${result.used.size}, defined: ${result.defined.size}, unscoped selectors: ${result.unscoped.length}`);
  console.log(`used but undefined (${result.missing.length}): ${result.missing.join(", ")}`);
  console.log(`defined but unused (${result.unused.length}): ${result.unused.join(", ")}`);
  if (process.argv.includes("--unscoped")) {
    console.log(result.unscoped.slice(0, 40).join("\n"));
  }
}
